using Impersonate.Application.Execution;
using Microsoft.Extensions.Options;
namespace Impersonate.Application.Pipelines;
public interface ITaskControlService { Task<PipelineOperationResult<bool>> ExecuteAsync(Guid projectId,Guid runId,Guid taskId,CancellationToken ct); }
public sealed class TaskControlService(IPipelineRunRepository runs,IExecutionInvocationStore invocations,IOptions<ExecutionOptions> options):ITaskControlService
{
 public async Task<PipelineOperationResult<bool>> ExecuteAsync(Guid projectId,Guid runId,Guid taskId,CancellationToken ct){var run=await runs.GetAsync(projectId,runId,ct);if(run is null)return PipelineOperationResult<bool>.Fail("not_found","Pipeline run was not found.");var task=run.Tasks.SingleOrDefault(x=>x.Id==taskId);if(task is null)return PipelineOperationResult<bool>.Fail("not_found","Task was not found.");var history=await invocations.ListAsync(task.Attempts.Select(x=>x.Id).ToArray(),ct);var coder=history.Where(x=>x.AgentRole=="Coder").ToList();if(coder.Sum(x=>x.InputTokenCount??0)>=options.Value.MaximumCoderTaskInputTokens||coder.Sum(x=>x.OutputTokenCount??0)>=options.Value.MaximumCoderTaskOutputTokens||coder.Sum(x=>Math.Max(1,x.PaidProviderRequestCount))>=options.Value.MaximumCoderPaidRequestsPerTask)return PipelineOperationResult<bool>.Fail("task_ai_budget_exhausted","The cumulative Coder AI budget for this task is exhausted; Retry Task is disabled.");try{run.StartTaskExecution(task);await runs.SaveChangesAsync(ct);return PipelineOperationResult<bool>.Ok(true);}catch(InvalidOperationException ex){return PipelineOperationResult<bool>.Fail("conflict",ex.Message);}}
}
